import { S3Client, PutObjectCommand, HeadBucketCommand, PutBucketWebsiteCommand } from '@aws-sdk/client-s3';
import { CloudFrontClient, CreateInvalidationCommand, GetDistributionCommand } from '@aws-sdk/client-cloudfront';
import { readFileSync, existsSync } from 'fs';

const ACCESS_KEY = 'AKIASAJBIV7CECCECRRV';
const SECRET_KEY = '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';
const REGION = 'us-east-1';
const DIST_ID = 'E1C0DEI0VKCUYN';
const BUCKET = 'ivxholding.com';

const s3 = new S3Client({
  region: REGION,
  credentials: { accessKeyId: ACCESS_KEY, secretAccessKey: SECRET_KEY },
});
const cf = new CloudFrontClient({
  region: 'us-east-1',
  credentials: { accessKeyId: ACCESS_KEY, secretAccessKey: SECRET_KEY },
});

const LANDING_DIR = '/home/user/rork-app/expo/ivxholding-landing';
const ASSETS_DIR = '/home/user/rork-app/expo/assets/images';

const files = [
  { path: `${LANDING_DIR}/index.html`, key: 'index.html', type: 'text/html; charset=utf-8', cache: 'no-cache, no-store, must-revalidate' },
  { path: `${LANDING_DIR}/capture.html`, key: 'capture.html', type: 'text/html; charset=utf-8', cache: 'no-cache, no-store, must-revalidate' },
  { path: `${LANDING_DIR}/capture.html`, key: 'capture', type: 'text/html; charset=utf-8', cache: 'no-cache, no-store, must-revalidate' },
  { path: `${LANDING_DIR}/enterprise-register.html`, key: 'enterprise-register.html', type: 'text/html; charset=utf-8', cache: 'no-cache, no-store, must-revalidate' },
  { path: `${LANDING_DIR}/enterprise-register.html`, key: 'enterprise-register', type: 'text/html; charset=utf-8', cache: 'no-cache, no-store, must-revalidate' },
  { path: `${LANDING_DIR}/robots.txt`, key: 'robots.txt', type: 'text/plain; charset=utf-8', cache: 'public, max-age=3600' },
  { path: `${LANDING_DIR}/sitemap.xml`, key: 'sitemap.xml', type: 'application/xml; charset=utf-8', cache: 'public, max-age=3600' },
  { path: `${LANDING_DIR}/ivx-reels.js`, key: 'ivx-reels.js', type: 'application/javascript; charset=utf-8', cache: 'public, max-age=300' },
];

const brandAssets = [
  { src: `${ASSETS_DIR}/ivx-logo.png`, key: 'ivx-logo.png', type: 'image/png' },
  { src: `${ASSETS_DIR}/ivx-symbol.png`, key: 'ivx-symbol.png', type: 'image/png' },
  { src: `${ASSETS_DIR}/ivx-og-image.png`, key: 'ivx-og-image.png', type: 'image/png' },
  { src: `${ASSETS_DIR}/favicon.png`, key: 'favicon.png', type: 'image/png' },
];

// Inject Supabase + API config into index.html
function injectConfig(html) {
  const supabaseUrl = process.env.EXPO_PUBLIC_SUPABASE_URL || '';
  const supabaseKey = process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY || '';
  const apiUrl = 'https://api.ivxholding.com';
  html = html.replace(/__IVX_API_BASE_URL__/g, apiUrl);
  html = html.replace(/__IVX_SUPABASE_URL__/g, supabaseUrl);
  html = html.replace(/__IVX_SUPABASE_ANON_KEY__/g, supabaseKey);
  html = html.replace(/__IVX_BACKEND_URL__/g, apiUrl);
  html = html.replace(/__IVX_APP_URL__/g, '');
  html = html.replace(/__IVX_GOOGLE_ADS_KEY__/g, '');
  html = html.replace(/__IVX_META_PIXEL_ID__/g, '');
  html = html.replace(/__IVX_TIKTOK_PIXEL_ID__/g, '');
  html = html.replace(/__IVX_LINKEDIN_PARTNER_ID__/g, '');
  return html;
}

async function deploy() {
  console.log('🚀 Deploying IVX landing page to S3...');
  console.log(`   Bucket: ${BUCKET}, Region: ${REGION}`);

  // Verify bucket access
  try {
    await s3.send(new HeadBucketCommand({ Bucket: BUCKET }));
    console.log('   ✅ Bucket accessible');
  } catch (e) {
    console.error(`   ❌ Bucket access failed: ${e.message}`);
    process.exit(1);
  }

  let okCount = 0;
  let failCount = 0;

  // Upload HTML + text files
  for (const file of files) {
    if (!existsSync(file.path)) {
      console.log(`   ⚠️  Skip ${file.key} — source not found`);
      failCount++;
      continue;
    }
    let body = readFileSync(file.path, 'utf-8');
    if (file.key === 'index.html') {
      body = injectConfig(body);
      // Verify 0 spinners
      const spinnerCount = (body.match(/spinner/gi) || []).length;
      const pulseCount = (body.match(/ivx-pulse/gi) || []).length;
      console.log(`   📊 index.html: ${spinnerCount} spinner refs, ${pulseCount} ivx-pulse refs`);
    }
    if (file.key === 'enterprise-register.html' || file.key === 'capture.html' || file.key === 'capture' || file.key === 'enterprise-register') {
      body = body.replace(/__IVX_API_BASE_URL__/g, 'https://api.ivxholding.com');
      body = body.replace(/__IVX_BACKEND_URL__/g, 'https://api.ivxholding.com');
    }
    try {
      await s3.send(new PutObjectCommand({
        Bucket: BUCKET,
        Key: file.key,
        Body: body,
        ContentType: file.type,
        CacheControl: file.cache,
      }));
      console.log(`   ✅ ${file.key} (${body.length} bytes)`);
      okCount++;
    } catch (e) {
      console.error(`   ❌ ${file.key}: ${e.message}`);
      failCount++;
    }
  }

  // Upload brand assets
  for (const asset of brandAssets) {
    if (!existsSync(asset.src)) {
      console.log(`   ⚠️  Skip ${asset.key} — source not found`);
      failCount++;
      continue;
    }
    const buffer = readFileSync(asset.src);
    try {
      await s3.send(new PutObjectCommand({
        Bucket: BUCKET,
        Key: asset.key,
        Body: buffer,
        ContentType: asset.type,
        CacheControl: 'public, max-age=86400',
      }));
      console.log(`   ✅ ${asset.key} (${buffer.length} bytes)`);
      okCount++;
    } catch (e) {
      console.error(`   ❌ ${asset.key}: ${e.message}`);
      failCount++;
    }
  }

  // Upload ivx-config.json
  const config = JSON.stringify({
    supabaseUrl: process.env.EXPO_PUBLIC_SUPABASE_URL || '',
    supabaseAnonKey: process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY || '',
    apiBaseUrl: 'https://api.ivxholding.com',
    backendUrl: 'https://api.ivxholding.com',
    deployedAt: new Date().toISOString(),
  });
  try {
    await s3.send(new PutObjectCommand({
      Bucket: BUCKET,
      Key: 'ivx-config.json',
      Body: config,
      ContentType: 'application/json',
      CacheControl: 'no-cache, no-store, must-revalidate',
    }));
    console.log(`   ✅ ivx-config.json`);
    okCount++;
  } catch (e) {
    console.error(`   ❌ ivx-config.json: ${e.message}`);
    failCount++;
  }

  // CloudFront invalidation
  console.log('\n🔄 Invalidating CloudFront...');
  try {
    const inv = await cf.send(new CreateInvalidationCommand({
      DistributionId: DIST_ID,
      InvalidationBatch: {
        CallerReference: `deploy-landing-${Date.now()}`,
        Paths: { Quantity: 1, Items: ['/*'] },
      },
    }));
    console.log(`   ✅ CloudFront invalidation: ${inv.Invalidation?.Id} (takes 1-2 min)`);
  } catch (e) {
    console.error(`   ❌ CloudFront invalidation failed: ${e.message}`);
  }

  console.log(`\n🎉 DEPLOY COMPLETE: ${okCount} ok, ${failCount} failed`);
}

deploy().catch(e => { console.error('Deploy failed:', e.message); process.exit(1); });
SCRIPT
